export function shopRows(s,{E,esc},query='',floor='all',availability='ready'){
 const normalize=v=>String(v).normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 const all=[...new Set(E.mallOf(s).sections.flatMap(d=>d.stores))].map(E.storeById).filter(Boolean);
 const rows=all.filter(st=>(floor==='all'||E.storeFloor(E.mallOf(s),st.id)===Number(floor))&&(availability==='saved'?(s.savedShops||[]).includes(st.id):availability==='all'||st.count||E.isServiceStore(st)||st.businessKind==='food')&&normalize(st.name+' '+st.range).includes(normalize(query))).sort((a,b)=>(E.storeFloor(E.mallOf(s),a.id)!==(s.floor||0))-(E.storeFloor(E.mallOf(s),b.id)!==(s.floor||0))||a.name.localeCompare(b.name));
 return `<p class="shop-results-count" role="status">${rows.length} matching shops · ${availability==='saved'?'Your saved shops':availability==='ready'?'Collections, services & game dining':'All locations'}</p>${rows.map(st=>`<button class="shop-destination" data-action="visit" data-id="${st.id}"><span class="shop-monogram" style="--shop:${st.color}">${esc(st.name.slice(0,2))}</span><span><strong>${esc(st.name)}</strong><small>${esc(E.planFor(s).levels[E.storeFloor(E.mallOf(s),st.id)])} · ${st.count?st.count+' real products':E.isServiceStore(st)?'Bookable services':st.businessKind==='food'?'Game dining · original menu':'Explore only · collection in research'}</small><b>Walk here & enter →</b></span></button>`).join('')||(availability==='saved'&&!query?'<p>No saved shops in this center yet. Open a shop’s guide and choose Save this shop.</p>':'<p>No shops match. Try another name or floor.</p>')}`;
}
export function shoppingGuide(s,id,{E,esc},count=0){
 const st=id&&E.storeById(id);
 if(!st)return `<div class="eyebrow">YOUR SHOPPING DAY</div><h2>Where shall we go?</h2><p>Find a shop, a public activity or a quiet place to rest. The map shows what you can do on every floor.</p><button class="button orange wide" data-action="map-panel" data-id="shops">Find a shop</button><button class="button secondary wide" data-action="center-map">Map & things to do</button><div class="play-detours"><button data-action="map-panel" data-id="services">Rest, food & friends</button><button data-action="commons-notebook">My discoveries · ${E.commonsStatus(s).count}/3</button><button data-action="view" data-id="journal">Stories & shared afternoons</button><button data-action="view" data-id="wardrobe">My purchases & outfits</button><button data-action="end-day">Go home & sleep</button></div>`;
 if(st.businessKind==='food'&&!st.count)return `<div class="eyebrow">YOU ARE INSIDE</div><h2>${esc(st.name)}</h2><p>Take a break with an original Mallside game meal. Review the price, then walk to a seat to dine.</p><button class="button orange wide" data-action="dining-open">Dining menu</button><button class="button secondary wide" data-action="leave-shop">Exit ${esc(st.name)} → Mall</button>`;
 const service=E.isServiceStore(st),pending=!service&&!st.count,steps=service?[['Choose a service','Read the time, price and recovery.'],['Reserve in game','Bookings appear below the menu.'],['Enjoy or refund','Use it here, or refund an unused booking.']]:pending?[['Explore the interior','This collection is still being researched.'],['Meet the associate','Ask about this shop and its game policies.'],['Find stocked shops','Use Shops to find verified collections.']]:[['Browse & inspect','Read a label or choose a product.'],[st.products.some(E.canTry)?'Choose your size':'Explore a demo',st.products.some(E.canTry)?'Try eligible clothes before buying.':'Read the label and try a product demo.'],['Review & pay','Only checkout spends game money.']];
 return `<div class="eyebrow">YOU ARE INSIDE</div><h2>${esc(st.name)}</h2><p>${service?'Choose a booking, enjoy a session or manage unused reservations.':pending?'Explore this shop while its collection is being researched.':'Inspect a real product, then review your bag before paying.'}</p><ol class="shopping-steps">${steps.map(([title,detail],i)=>`<li><b>${i+1}</b><span>${title}<small>${detail}</small></span></li>`).join('')}</ol><button class="button orange wide" data-action="interior-browse">${service?'Services & my bookings':pending?'About this collection':'Browse this shop'}</button>${!service?`<button class="button secondary wide" data-action="play-bag">Review bag${count?' · '+count+' items':''}</button>`:''}<button class="button secondary wide" data-action="leave-shop">Exit ${esc(st.name)} → Mall</button>`;
}
export function campusMapSVG(layout,position,floor,{E,esc}){
 const c=layout.campus;
 const paths=c.halls.map(e=>{const a=c.nodes[Number(e.a)],b=c.nodes[Number(e.b)];return `<path d="M${a.x} ${a.y}L${b.x} ${b.y}" stroke="#fff9eb" stroke-width="${e.width}" stroke-linecap="round"/>`;}).join('')+c.courts.map(n=>`<circle cx="${n.x}" cy="${n.y}" r="${n.radius}" fill="#fff9eb"/>`).join('');
 const blocks=[...layout.units,...layout.rects,...layout.anchors].map(r=>{const st=E.storeById(r.id),shape=`<rect x="${r.x}" y="${r.y}" width="${r.width}" height="${r.height}" rx="5" fill="${st?.count?'#9a684c':st&&(E.isServiceStore(st)||st.businessKind==='food')?'#698879':'#b7bcaa'}"/>`;return st?`<a href="#shop" data-action="center-unit" data-id="${r.id}" aria-label="Walk to ${esc(st.name)} and enter"><title>${esc(st.name)} · ${st.count?st.count+' products':E.isServiceStore(st)?'Services':st.businessKind==='food'?'Original game dining':'Collection in research'}</title>${shape}</a>`:shape;}).join('');
 const nodes=c.nodes.map(n=>`<a href="#court" data-action="center-zone" data-floor="${floor}" data-id="${n.id}" aria-label="Walk to ${esc(n.label)}"><circle cx="${n.x}" cy="${n.y}" r="32" fill="#496e58"/><text x="${n.x}" y="${n.y-50}" text-anchor="middle" font-size="32" fill="#294d40">${esc(n.label)}</text></a>`).join('');
 const connectors=layout.escalators.map(e=>`<a href="#connection" data-action="center-stop" data-type="connector" data-floor="${floor}" data-id="${e.id}" aria-label="Walk to a floor connection"><rect x="${e.landing.x-25}" y="${e.landing.y-25}" width="50" height="50" rx="9" fill="#4e6580"/><text x="${e.landing.x}" y="${e.landing.y+12}" text-anchor="middle" font-size="34" fill="white">↕</text></a>`).join('');
 const publicMarkers=layout.environment.fixtures.filter(f=>f.activity||f.amenity||f.kind==='art').map(f=>`<a href="#public-stop" data-action="center-stop" data-type="fixture" data-floor="${floor}" data-id="${f.id}" aria-label="Walk to ${esc(f.kind==='art'?'Sculpture alcove':f.amenity?(f.amenity==='water'?'Water refill station':'Community noticeboard'):({mosaic:'Mosaic table',reading:'Reading shelf',garden:'Garden study'})[f.activity])}"><circle cx="${f.approach.x}" cy="${f.approach.y}" r="25" fill="#865588" stroke="white" stroke-width="5"/><text x="${f.approach.x}" y="${f.approach.y+10}" text-anchor="middle" font-size="27" fill="white">✦</text></a>`).join('');
 const marker=position?`<g><circle cx="${position.x}" cy="${position.y}" r="30" fill="#9c4629" stroke="white" stroke-width="10"/><text x="${position.x}" y="${position.y+75}" text-anchor="middle" font-size="36" font-weight="bold" fill="#593821">YOU</text></g>`:'';
 return `<svg class="campus-plan" viewBox="0 0 ${c.width} ${c.height}" role="group" aria-label="Interactive center map: choose a storefront or court"><rect width="100%" height="100%" rx="50" fill="#d4dece"/>${paths}${blocks}${nodes}${connectors}${publicMarkers}${marker}</svg>`;
}

export function shopFinderShortcuts(s,availability,{E}){const ids=new Set(E.mallOf(s).sections.flatMap(d=>d.stores)),count=(s.savedShops||[]).filter(id=>ids.has(id)).length;return `<div class="shop-finder-quick" role="group" aria-label="Shop list shortcuts"><button class="button secondary" data-action="shop-finder-mode" data-id="ready" aria-pressed="${availability==='ready'}">Collections & activities</button><button class="button secondary" data-action="shop-finder-mode" data-id="saved" aria-pressed="${availability==='saved'}">Saved shops · ${count}</button></div>`;}
